css:
.payment-advice-table {
    width: 800px; 
    border-collapse: collapse;
    font-family: Arial, sans-serif;
    font-size: 10pt;
    margin: 20px auto;
    border: 1px solid black; 
}

/* Cell and Header Styles */
.payment-advice-table th, 
.payment-advice-table td {
    border: 1px solid black;
    padding: 6px 10px;
    text-align: left;
}

.payment-advice-table th {
    background-color: #f5f5f5;
    font-weight: bold;
    padding-top: 10px;
    padding-bottom: 10px;
}

.payment-advice-table thead th {
    border: none; 
}
.payment-advice-table thead p {
    margin: 0;
}
.payment-advice-table thead th:last-child {
    font-size: 14pt; 
}

.payment-advice-table tbody tr:nth-child(1) td {
    border-top: none;
    border-bottom: none;
}
.payment-advice-table tbody tr:nth-child(1) td:first-child {
    border-right: none;
}
.payment-advice-table tbody tr:nth-child(1) td:last-child {
    border-left: none; 
    text-align: right;
}

.payment-advice-table tbody tr:nth-child(2) td {
    border-top: none;
    border-bottom: 1px solid black;
    padding-top: 10px;
    padding-bottom: 10px;
}

.payment-advice-table tr:nth-child(3) th, 
.payment-advice-table tr:nth-child(7) th {
    text-align: center;
}

.payment-advice-table td:last-child,
.payment-advice-table th:last-child {
    text-align: right;
}

.payment-advice-table tr:nth-child(5) td, 
.payment-advice-table tr:nth-child(10) td {
    font-weight: bold;
}
.payment-advice-table tr:nth-child(5) td:first-child,
.payment-advice-table tr:nth-child(10) td:first-child {
    text-align: right; 
}

.payment-advice-table tr:nth-child(6) td {
    border: none;
    padding: 10px 6px 5px 6px;
}

.payment-advice-table tr:nth-child(11) td {
    border: none;
    padding-top: 30px;
    padding-bottom: 5px;
}

.payment-advice-table tfoot td {
    border: none;
    height: 100px;
    vertical-align: bottom;
    padding-top: 5px; 
}

.signature-line {
    border-top: 1px solid black;
    width: 180px;
    margin-bottom: 5px;
}

.payment-advice-table tfoot td:last-child .signature-line {
    margin-left: auto; 
}
.payment-advice-table tfoot td:last-child p {
    text-align: right;
}
.print-format td, .print-format th {
padding: 5px !important;
}
.print-format th {
color: black;
border-bottom-width: 1px !important;
font-weight: 600;
}
